using System.Net;
using System.Net.Http.Json;
using System.Security.Claims;
using System.Text.Json;
using Microsoft.AspNetCore.Components.Authorization;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Configuration;
using Osynix.Ats.Data;
using Osynix.Ats.Domain;
using Osynix.Ats.Services;
using Xunit;
namespace Osynix.Ats.Tests;
public class PositionCreationTests {
 static Position Vacancy()=>new(){Client="Selected Client",Title="Role",JobDescription="Original JD",Criteria=[new(){Name="Experience",Weight=100}]};
 [Theory][InlineData("Employer",true)][InlineData("Freelance Recruiter",false)][InlineData("Agency",false)]
 public void EveryAccountUsesAnalysisThenTextVerificationThenCriteriaApproval(string account,bool company){var p=Vacancy();p.Client=company?"":account+" Client";Assert.True(PositionCreationRules.CanOpenStep("basics",p,company,false,false,false));Assert.False(PositionCreationRules.CanOpenStep("jd",p,company,false,false,false));Assert.True(PositionCreationRules.CanOpenStep("jd",p,company,true,false,false));Assert.False(PositionCreationRules.CanOpenStep("criteria",p,company,true,false,false));Assert.True(PositionCreationRules.CanOpenStep("criteria",p,company,true,true,false));Assert.False(PositionCreationRules.CanOpenStep("status",p,company,true,true,false));Assert.True(PositionCreationRules.CanOpenStep("status",p,company,true,true,true));}
 [Fact]public void RequiredFieldsDistinguishCompanyFromClientWorkAndPermitMissingLocation(){var p=new Position();Assert.Contains("Client",PositionCreationRules.RequiredDetails(p,false));Assert.DoesNotContain("Client",PositionCreationRules.RequiredDetails(p,true));Assert.Contains("Position Title",PositionCreationRules.RequiredDetails(p,true));p.Title="JD Supplied Title";Assert.Empty(PositionCreationRules.RequiredDetails(p,true));p.Client="Client";Assert.Empty(PositionCreationRules.RequiredDetails(p,false));p.HiringTarget=0;Assert.Contains("Hiring Target (At Least 1)",PositionCreationRules.RequiredDetails(p,false));}
 [Fact]public void AutofillUsesJdFactsWithoutChangingClientAccountAssignmentsOrPublication(){var p=Vacancy();p.ClientId=Guid.NewGuid();p.AssignedRecruiter="selected-recruiter";p.HiringContact="Saved Contact";var id=p.ClientId;PositionCreationRules.Apply(p,new("Engineering Manager","Lead Engineering",[new(){Name="Engineering Leadership",Weight=100}],"Lahore","Engineering","Contract","Hybrid",2,"PKR 200,000–300,000 Monthly",200000,300000,"PKR","Monthly"));Assert.Equal("Engineering Manager",p.Title);Assert.Equal("Lahore",p.Location);Assert.Equal("Engineering",p.Department);Assert.Equal("Contract",p.EmploymentType);Assert.Equal("Hybrid",p.WorkArrangement);Assert.Equal(2,p.HiringTarget);Assert.Equal(200000m,p.SalaryMinimum);Assert.Equal(300000m,p.SalaryMaximum);Assert.Equal(id,p.ClientId);Assert.Equal("Selected Client",p.Client);Assert.Equal("selected-recruiter",p.AssignedRecruiter);Assert.Equal("Saved Contact",p.HiringContact);Assert.False(p.CareersPublished);Assert.False(p.CriteriaLocked);}
 [Fact]public void MissingJdFactsDoNotEraseManuallyEnteredDetailsOrInventSalary(){var p=Vacancy();p.Location="Manually Confirmed City";p.Department="Internal Department";PositionCreationRules.Apply(p,new("","Summary",[new(){Name="Experience",Weight=100}]));Assert.Equal("Role",p.Title);Assert.Equal("Manually Confirmed City",p.Location);Assert.Equal("Internal Department",p.Department);Assert.Null(p.SalaryMinimum);Assert.Null(p.SalaryMaximum);Assert.Equal(1,p.HiringTarget);}
 [Fact]public void SourceApprovalSurvivesVacancyCorrectionsButNotChangedJdOrClientRequirements(){var p=Vacancy();var signature=PositionCreationRules.SourceSignature(p);p.Title="Corrected Job Title";p.Location="Corrected Location";p.EmploymentType="Part-time";Assert.Equal(signature,PositionCreationRules.SourceSignature(p));p.JobDescription+=" New Requirement";Assert.NotEqual(signature,PositionCreationRules.SourceSignature(p));p=Vacancy();signature=PositionCreationRules.SourceSignature(p);p.ClientNotes="Additional Requirement";Assert.NotEqual(signature,PositionCreationRules.SourceSignature(p));p=Vacancy();signature=PositionCreationRules.SourceSignature(p);p.ClientId=Guid.NewGuid();Assert.NotEqual(signature,PositionCreationRules.SourceSignature(p));}
 [Fact]public void CriteriaChangesRequireFreshApprovalAndInvalidWeightsCannotPassFinalReview(){var p=Vacancy();var signature=PositionCreationRules.CriteriaSignature(p);p.Criteria[0].EvidenceExpected="Revised Evidence";Assert.NotEqual(signature,PositionCreationRules.CriteriaSignature(p));p.Criteria[0].Weight=90;Assert.False(PositionCreationRules.CanOpenStep("status",p,true,true,true,true));p.Criteria[0].Weight=100;Assert.True(PositionCreationRules.ValidCriteria(p));p.Criteria.Add(new(){Name="Experience",Weight=0});Assert.False(PositionCreationRules.ValidCriteria(p));}
 sealed class Admin:AuthenticationStateProvider{public override Task<AuthenticationState> GetAuthenticationStateAsync()=>Task.FromResult(new AuthenticationState(new ClaimsPrincipal(new ClaimsIdentity([new(ClaimTypes.NameIdentifier,"test-admin"),new(ClaimTypes.Role,"Admin")],"Test"))));}
 sealed class UnusedFactory:IDbContextFactory<AtsDbContext>{public AtsDbContext CreateDbContext()=>throw new InvalidOperationException("JD Draft Analysis Must Not Persist A Position.");}
 sealed class Provider:HttpMessageHandler{public string Request="";public int Calls;protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken ct){Calls++;Request=await request.Content!.ReadAsStringAsync(ct);var output=new{title="Engineering Manager",location="Lahore",department="Engineering",employmentType="Contract",workArrangement="Hybrid",hiringTarget=2,salaryRange="PKR 200000–300000 Monthly",salaryMinimum=200000,salaryMaximum=300000,salaryCurrency="PKR",salaryPeriod="Monthly",summary="Engineering Leadership",criteria=Enumerable.Range(1,4).Select(n=>new{name="Criterion "+n,weight=25,knockout=false,evidenceExpected="Evidence",scoringGuidance="Guidance",notes="",rationale="JD Requirement"})};return new(HttpStatusCode.OK){Content=JsonContent.Create(new{status="completed",output=new[]{new{content=new[]{new{type="output_text",text=JsonSerializer.Serialize(output)}}}}})};}}
 [Fact]public async Task JdAnalysisReturnsVacancyFactsAndCriteriaInOneCallWithoutSavingAnything(){var factory=new UnusedFactory();var provider=new Provider();var config=new ConfigurationBuilder().AddInMemoryCollection(new Dictionary<string,string?>{{"OpenAI:ApiKey","test-key"},{"OpenAI:Model","test-model"}}).Build();var ai=new AiService(new HttpClient(provider),config,factory,new Access(new Admin()),new DatabaseDocumentStore(factory));var result=await ai.AnalyzeJdDraft("Synthetic JD Evidence","Additional Hiring Requirement");Assert.Equal(1,provider.Calls);Assert.Equal("Engineering Manager",result.Title);Assert.Equal("Lahore",result.Location);Assert.Equal("Engineering",result.Department);Assert.Equal("Contract",result.EmploymentType);Assert.Equal("Hybrid",result.WorkArrangement);Assert.Equal(2,result.HiringTarget);Assert.Equal(200000m,result.SalaryMinimum);Assert.Equal(4,result.Criteria.Count);Assert.Equal(100,result.Criteria.Sum(c=>c.Weight));Assert.Contains("Never infer",provider.Request);Assert.Contains("salaryMinimum",provider.Request);Assert.DoesNotContain("Assign A Recruiter",provider.Request);}
}
